System.Resources.ResourceManager  rm = new System.Resources.ResourceManager("Resources.Strings",System.Reflection.Assembly.Load("App_GlobalResources"));

private void xrPivotGrid1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 xrPivotGrid1.BestFit();
 xrPivotGrid1.CanGrow = true;
 xrPivotGrid1.CanShrink = true;
}

private void xrPivotGrid1_CustomFieldSort(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotGridCustomFieldSortEventArgs e) {
  if (e.Field.FieldName == "muaji")
            {
                int vl1 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex1, "indeksViti"));
                int vl2 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex2, "indeksViti"));
                int m1 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex1, "indeksMuaji"));
                int m2 = Convert.ToInt32(e.GetListSourceColumnValue(e.ListSourceRowIndex2, "indeksMuaji"));

                if (m1 == m2)
                {
                    e.Result = -1 * vl1.CompareTo(vl2);

                }
                else
                    e.Result = m1.CompareTo(m2);
                e.Handled = true;
            }
}

private void xrPivotGrid1_FieldValueDisplayText(object sender, DevExpress.XtraReports.UI.PivotGrid.PivotFieldDisplayTextEventArgs e) {
if (e.ValueType == DevExpress.XtraPivotGrid.PivotGridValueType.GrandTotal && e.DisplayText == "Grand Total")
            {
                e.DisplayText = "Totali";
            }
}

private void Rap_DetyrimiKlienteveSipasMuajve_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

   DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldMenaxher = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Menaxher", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldMenaxher.FieldName = "AgjentiEmer";
            fieldMenaxher.Caption =  rm.GetString("labelMenaxher", parametraRaporti.Ci);
            fieldMenaxher.Options.ShowGrandTotal = true;

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldEmertimi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Emertimi", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldEmertimi.FieldName = "EMERTIMIKF";
            fieldEmertimi.Caption =  rm.GetString("labelRaportiEmertimi", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldMonedha = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Monedha", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldMonedha.FieldName = "MONEDHAKOD";
            fieldMonedha.Caption =  rm.GetString("labelFilterAvancuarMonedha", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldLimiti = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Limiti", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldLimiti.FieldName = "LIMITBLLOKUES";
            fieldLimiti.Caption =  rm.GetString("labelRaportLimiti", parametraRaporti.Ci);


            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldmuaji = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("muaji", DevExpress.XtraPivotGrid.PivotArea.ColumnArea);
            fieldmuaji.FieldName = "muaji";
            fieldmuaji.Caption = "muaji";
            fieldmuaji.SortMode = DevExpress.XtraPivotGrid.PivotSortMode.Custom;

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldDetyrimi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("totalikrahasues", DevExpress.XtraPivotGrid.PivotArea.DataArea);
            fieldDetyrimi.FieldName = "totalikrahasues";
            fieldDetyrimi.Caption = "Detyrimi";

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldQytet = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Qyteti", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldQytet.FieldName = "QYTETIEMRI";
            fieldQytet.Caption =  rm.GetString("labelQyteti", parametraRaporti.Ci);

            fieldDetyrimi.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldDetyrimi.CellFormat.FormatString = "{0:#,#.#0}";
            fieldLimiti.CellFormat.FormatString = "{0:#,#.#0}";
            xrPivotGrid1.Fields.Clear();
            xrPivotGrid1.Fields.AddRange(new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField[] {fieldMenaxher, fieldEmertimi, fieldMonedha, fieldLimiti,fieldQytet,
               fieldmuaji, fieldDetyrimi});
            xrPivotGrid1.Styles.FieldHeaderStyle = xrPivotGrid1.Styles.FieldHeaderStyle;

  var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var  filterMonedha = parameters.Find(param => param.Emri == "filterMonedha");
      var  filterMonedhaKF = parameters.Find(param => param.Emri == "monedhaKF");

        if (filterMonedha.Vlera == "" && filterMonedhaKF.Vlera =="True")
            {
                xrPivotGrid1.OptionsView.ShowColumnTotals = false;
                xrPivotGrid1.OptionsView.ShowRowTotals = false;
                xrPivotGrid1.OptionsView.ShowRowGrandTotalHeader = false;
                xrPivotGrid1.OptionsView.ShowColumnGrandTotalHeader = false;
                xrPivotGrid1.OptionsView.ShowCustomTotalsForSingleValues = false;
                xrPivotGrid1.OptionsView.ShowRowGrandTotals = false;

            }
            xrPivotGrid1.Styles.FieldHeaderStyle = xrPivotGrid1.Styles.FieldHeaderStyle;
            xrPivotGrid1.Styles.FieldValueStyle = xrPivotGrid1.Styles.FieldHeaderStyle;
            xrPivotGrid1.FieldValueGrandTotalStyleName = xrPivotGrid1.Styles.FieldHeaderStyle.Name;
}
